t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
forms={
 'gamma': lambda p: p[0]*t**p[1]*np.exp(-p[2]*t),
 'gamma_inv': lambda p: p[0]*t**p[1]*np.exp(-p[2]*t-p[3]/t),
 'oneexp_t2': lambda p: p[0]*(1-np.exp(-p[1]*t**p[4]))*np.exp(-p[2]*t-p[3]/t),
 'exp_pow': lambda p: p[0]*np.exp(-p[1]*t**p[2])*t**p[3],
 'lin_exp': lambda p: p[0]*np.exp(-p[1]*t)*(1-np.exp(-p[2]*t**2)),
 'rat': lambda p: p[0]*t/(1+p[1]*t**p[2]) ,
}
for name,f in forms.items():
    best=None
