import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
forms={
 'A_1expT2_expinv': lambda q: q[0]*(1-np.exp(-q[1]*t**2))*np.exp(-q[2]*t-q[3]/t)*t**q[4],
 'B_1exp_expinv_lin': lambda q: q[0]*(1-np.exp(-q[1]*t))*np.exp(-q[2]*t-q[3]/t)*t**q[4],
 'C_expinv_pow': lambda q: q[0]*np.exp(-q[2]*t-q[3]/t)*t**q[4]*(1-np.exp(-q[1]*t**2)),
 'D_expinv_only': lambda q: q[0]*np.exp(-q[2]*t-q[3]/t)*t**q[4],
}
for name,f in forms.items():
    best=None
    for s in range(40):
        rng=np.random.default_rng(s)
        p0=np.concatenate([rng.uniform(0.2,5,1),rng.uniform(0.1,3,1),rng.uniform(0,1,1),rng.uniform(0,2,1),rng.uniform(-1,3,1),[0.013,1.5]])
        def res(p):
            S=f(p[:5])
            r=y-(S-p[5]*t**2*A**p[6])
            return r if np.all(np.isfinite(r)) else np.full(len(t),1e3)
        try: r=least_squares(res,p0)
        except Exception: continue
        if best is None or r.cost<best.cost: best=r
    print(name, "%.3e"%np.sqrt(np.mean(best.fun**2)), np.round(best.x,4))
